package com.jarvis.mobile.brain;
import android.content.*; import java.util.*; import com.jarvis.mobile.actions.AndroidActionRouter;
public class JarvisBrain { Context c; SharedPreferences mem; AndroidActionRouter actions; public JarvisBrain(Context c){this.c=c;mem=c.getSharedPreferences("jarvis_memory",0);actions=new AndroidActionRouter(c);} public String handle(String raw){String q=raw.trim(),l=q.toLowerCase(Locale.ROOT); if(l.startsWith("remember ")){String v=q.substring(9).trim();mem.edit().putString("last",v).apply();return "I'll remember that.";} if(l.equals("recall")||l.contains("what did i tell you")){String v=mem.getString("last","");return v.isEmpty()?"I don't have a saved memory yet.":v;} String a=actions.execute(q); if(a!=null)return a; return "I heard you. This beta understands phone actions, apps, calls, messages, email, calendar, navigation, alarms, timers, media, memory, and screen control."; } }
